package pe.upn.yapaa_api.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.*;import pe.upn.yapaa_api.security.UsuarioActual;import pe.upn.yapaa_api.exception.*;import java.util.*;
@Service public class DireccionesService {
 public record Direccion(Integer id,String nombre,String direccion,String referencia,double latitud,double longitud,boolean predeterminada){}
 private final JdbcTemplate jdbc;private final UsuarioActual usuario;private final MapasService mapas;
 public DireccionesService(JdbcTemplate j,UsuarioActual u,MapasService m){jdbc=j;usuario=u;mapas=m;}
 public int cliente(){if(!usuario.tieneRol("CLIENTE")||usuario.tieneRol("NEGOCIO"))throw new org.springframework.security.access.AccessDeniedException("Solo clientes pueden gestionar direcciones.");return usuario.obtenerCuenta().getIdCuenta();}
 public static final RowMapper<Direccion> MAPPER=(r,n)->new Direccion(r.getInt("id_direccion"),r.getString("nombre"),r.getString("direccion"),r.getString("referencia"),r.getDouble("latitud"),r.getDouble("longitud"),r.getBoolean("predeterminada"));
 @Transactional(readOnly=true) public List<Direccion> listar(){return jdbc.query("SELECT * FROM direccion_cliente WHERE id_cuenta=? AND activa=1 ORDER BY predeterminada DESC,id_direccion",MAPPER,cliente());}
 public Direccion propia(int id){return jdbc.query("SELECT * FROM direccion_cliente WHERE id_cuenta=? AND id_direccion=? AND activa=1",MAPPER,cliente(),id).stream().findFirst().orElseThrow(()->new RecursoNoEncontradoException("Dirección no encontrada."));}
 private void bloquear(int id){jdbc.queryForObject("SELECT id_cuenta FROM cuenta WITH (UPDLOCK,HOLDLOCK) WHERE id_cuenta=?",Integer.class,id);}
 @Transactional public Direccion guardar(String nombre,String referencia,String token,boolean predeterminada){int id=cliente();bloquear(id);nombre=nombre==null?"":nombre.strip();referencia=referencia==null?"":referencia.strip();if(nombre.isBlank()||nombre.length()>40||referencia.length()>120||nombre.chars().anyMatch(Character::isISOControl)||referencia.chars().anyMatch(Character::isISOControl))throw new ReglaNegocioException("Revisa el nombre y la referencia de la dirección.");
 int cantidad=jdbc.queryForObject("SELECT COUNT(*) FROM direccion_cliente WHERE id_cuenta=? AND activa=1",Integer.class,id);if(cantidad>=10)throw new ReglaNegocioException("Puedes guardar hasta diez direcciones.");if(jdbc.queryForObject("SELECT COUNT(*) FROM direccion_cliente WHERE id_cuenta=? AND activa=1 AND nombre=?",Integer.class,id,nombre)>0)throw new ReglaNegocioException("Ya tienes una dirección con ese nombre.");var p=mapas.validar(token);CoberturaTrujillo.exigir(p.latitud(),p.longitud());if(p.direccion().length()+(referencia.isBlank()?0:3+referencia.length())>250)throw new ReglaNegocioException("Acorta la referencia de la dirección.");boolean defecto=predeterminada||cantidad==0;if(defecto)jdbc.update("UPDATE direccion_cliente SET predeterminada=0 WHERE id_cuenta=?",id);
 Integer nueva=jdbc.queryForObject("INSERT INTO direccion_cliente(id_cuenta,nombre,direccion,referencia,latitud,longitud,predeterminada) OUTPUT INSERTED.id_direccion VALUES(?,?,?,?,?,?,?)",Integer.class,id,nombre,p.direccion(),referencia,p.latitud(),p.longitud(),defecto);return propia(nueva);}
 @Transactional public void predeterminada(int id){int cuenta=cliente();bloquear(cuenta);propia(id);jdbc.update("UPDATE direccion_cliente SET predeterminada=0 WHERE id_cuenta=?",cuenta);jdbc.update("UPDATE direccion_cliente SET predeterminada=1 WHERE id_direccion=? AND id_cuenta=?",id,cuenta);}
 @Transactional public void eliminar(int id){int cuenta=cliente();bloquear(cuenta);var d=propia(id);jdbc.update("UPDATE direccion_cliente SET activa=0,predeterminada=0 WHERE id_direccion=? AND id_cuenta=?",id,cuenta);if(d.predeterminada())jdbc.update("UPDATE direccion_cliente SET predeterminada=1 WHERE id_direccion=(SELECT TOP 1 id_direccion FROM direccion_cliente WHERE id_cuenta=? AND activa=1 ORDER BY id_direccion)",cuenta);}
}
